local OverseaStoreCommonCell = Class("OverseaStoreCommonCell")

--region lifecycle
function OverseaStoreCommonCell:__init()
    self._storeType = nil
    self._cellData  = nil
end

function OverseaStoreCommonCell:__delete()
    self._storeType = nil
    self._cellData  = nil
end

function OverseaStoreCommonCell:Awake()
    self:InitHandler()
end

function OverseaStoreCommonCell:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function OverseaStoreCommonCell:InitHandler()
    SetButtonAction(self.obj, Bind(self, self.CellOnClickHandler))
end
--endregion init

--region handler
---cell点击回调
function OverseaStoreCommonCell:CellOnClickHandler()
    if self._storeType == OverseaStoreConstants.StoreType.TimeLimitActivity then
        xRecord.record("5-016", string.format('click_activity_%d', checkInt(self._cellData.icon)))
    elseif self._storeType == OverseaStoreConstants.StoreType.GiftDaily
            or self._storeType == OverseaStoreConstants.StoreType.GiftWeekly
            or self._storeType == OverseaStoreConstants.StoreType.GiftEquipment
            or self._storeType == OverseaStoreConstants.StoreType.GiftWeapon then
        xRecord.record("5-009", string.format('click_pack_%d', checkInt(self._cellData.icon)))
    end
    OverseaStoreMgr:OpenBuyItemDialog(self._cellData, self._storeType , true)
end
--endregion handler

--region public
---刷新cell
---@param storeType OverseaStoreConstants.StoreType
---@param data table
function OverseaStoreCommonCell:RefreshCell(storeType, data)
    self._storeType = storeType
    self._cellData = data

    self:RefreshCellState(data)
    self:RefreshTimeGroup(data)
    self:RefreshGoods(data)
    self:RefreshPrice(data)
    self:RefreshNewIcon(storeType, data)

end

---播放cell动画
function OverseaStoreCommonCell:PlayAnimation()
 
end

---更新剩余时间显示
function OverseaStoreCommonCell:UpdateTimeGroupText(data)
    local seconds = checkInt(data.endTime)
    if seconds <= 0 then return end

    CfUtils.FillText(self.Txtday, CfUtils.GetTimeHMS(seconds))
end
--endregion public

--region private
---刷新cell状态
function OverseaStoreCommonCell:RefreshCellState(data)
    local isSoldOut = OverseaStoreUtils.ProductIsSoldOut(data)

    local isGray = isSoldOut or false
    KTool.SetActive(self.DisableMask, isGray)
    KTool.SetActive(self.FinishGroup, isSoldOut)
    
end

---刷新剩余时间
function OverseaStoreCommonCell:RefreshTimeGroup(data)
    local seconds = checkInt(data.endTime)
    if seconds <= 0 then
        CfUtils.SetActive(self.TimerGroup, false)
        return
    end

    CfUtils.SetActive(self.TimerGroup, true)
    self:UpdateTimeGroupText(data)
end

---刷新道具
function OverseaStoreCommonCell:RefreshGoods(data)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.icon))
    if not vo then return end

    local goodsType = GoodsUtils.GetIdType(vo.id)
    if goodsType == Constants.IDType.GoodsHeadOrFrame then
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.CommonPlayerHeadNodeStub, true)
        local headNode = self:GetHeadNode()
        if headNode then
            ---@type CommonPlayerHeadNode
            local headEnv  = CfUtils.GetLuaScr(headNode, "Game.Behaviours.CommonPlayerHeadNode")
            if headEnv then
                --种类区分：1头像2头像框3徽章4主题
                if checkNumber(vo.kind) == 1 then
                    headEnv:FreshHeadIcon(vo.id, true)
                elseif checkNumber(vo.kind) == 2  then
                    headEnv:FreshFrame(vo.id, true)
                end
            end
        end
    else
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetActive(self.CommonPlayerHeadNodeStub, false)
        CfUtils.FillImage(self.ImgIcon, vo.photoPath)
    end
    
    local name = vo.name
    if checkInt(data.num) > 1 then
        name = string.format('%s x%d', name, checkInt(data.num))
    end
    CfUtils.FillText(self.TxtDesc1, name)
    
    -- 品质
    CfUtils.SetUISwitchImage(self.GoodQuality, vo.quality)
    
    -- 星级
    local starGroup = self.controller.transform:Find('BtnNode/Star')
    for i = 1, starGroup.childCount do
        local go = starGroup.transform:Find("ImgStar"..i)
        if isNotNull(go) then
            CfUtils.SetActive(go, checkInt(vo.quality) >= i)
        end
    end

    -- 库存
    if checkNumber(data.stock) == -1 then
        KTool.SetActive(self.GroupDesc2, false)
    else
        KTool.SetActive(self.GroupDesc2, true)
        CfUtils.FillText(self.TxtNumber, data.currentStock)
    end
    
    local tabType = checkInt(data.iconId)
    if tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityGroup, false)
        CfUtils.SetActive(self.TimeLimitGroup, false)
    elseif tabType == TagType.Recommend then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityGroup, true)
        CfUtils.SetActive(self.TimeLimitGroup, false)
    elseif tabType == TagType.All then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityGroup, true)
        CfUtils.SetActive(self.TimeLimitGroup, false)
    elseif tabType == TagType.TimeLimit then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityGroup, false)
        CfUtils.SetActive(self.TimeLimitGroup, true)
    elseif tabType == TagType.TimAndRec then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityGroup, true)
        CfUtils.SetActive(self.TimeLimitGroup, true)
    else
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityGroup, false)
        CfUtils.SetActive(self.TimeLimitGroup, false)
    end
end

---刷新价格
function OverseaStoreCommonCell:RefreshPrice(data)
    local isFree = OverseaStoreUtils.ProductIsFree(data)
    KTool.SetActive(self.PriceGroup, not isFree)
    KTool.SetActive(self.FreeGroup, isFree)

    if isFree then return end

    local curPriceTxt = self.CurPrice:Find('TextNumber') 
    if isNotNull(data.payPoint) then
        -- 货币购买
        CfUtils.SetActive(self.CurPrice, true)
        CfUtils.SetActive(self.OriPrice, false)
        CfUtils.SetActive(self.CurPriceIcon, false)
        CfUtils.FillText(curPriceTxt, CfUtils.GetDisplayPrice(data.price, data.channelProductId))
        return 
    end
    
    if not data.prices then return end
    
    local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.prices[1].currency))
    KTool.SetActive(self.CurPrice, true)
    CfUtils.SetActive(self.CurPriceIcon, true)
    CfUtils.FillImage(self.CurPriceIcon, currencyVo.photoPath)  
    CfUtils.FillText(curPriceTxt, data.prices[1].current)
    if checkInt(data.prices[1].original) == 0 then
        KTool.SetActive(self.OriPrice, false)
    else
        KTool.SetActive(self.OriPrice, true)
        CfUtils.FillText(self.OriPriceTxt, data.prices[1].original)
        CfUtils.FillImage(self.OriPriceIcon, currencyVo.photoPath)
        CfUtils.SetActive(self.OriPriceIcon, true)
    end
end

---刷新new标识
function OverseaStoreCommonCell:RefreshNewIcon(storeType, data)
    CfUtils.SetActive(self.ImgNew, OverseaStoreMgr:IsNewStoreProduct(storeType, data.productId))
end


function OverseaStoreCommonCell:GetHeadNode()
    if self.CommonPlayerHeadNode then
        return self.CommonPlayerHeadNode
    end
    self.CommonPlayerHeadNode = self.CommonPlayerHeadNodeStub:InstantiatePrefab("CommonPlayerHeadNode")
    ---@type UnityEngine.UI.Image
    local commonPlayerHeadNodeImgMain = self.CommonPlayerHeadNode:Find('Root/ImgMain'):GetComponent(ImageType)
    commonPlayerHeadNodeImgMain.raycastTarget = false
    return self.CommonPlayerHeadNode
end

--endregion private

return OverseaStoreCommonCell